# Texts may only use A-Z, 0-9, space and . , ' : ( ) - ^   (the game's font); title <= 28 letters, lines <= 58.
import math, decimal
from decimal import Decimal

def A(m, e): return int(Decimal(str(m)).scaleb(e))
def P2(e, minus=0):                                   # 2^e - minus, as digits (long ones go through Decimal: no 4300-digit limit)
    def f():
        c = decimal.Context(prec=int(e * 0.30103) + 20, Emax=decimal.MAX_EMAX, traps=[])
        r = c.power(Decimal(2), e)
        return str(c.subtract(r, Decimal(minus)) if minus else r)
    return f
def first_pow2_with(digits): return math.ceil((digits - 1) / math.log10(2))
def bell(n):
    row = [1]
    for _ in range(n - 1):
        new = [row[-1]]
        for x in row: new.append(new[-1] + x)
        row = new
    return row[-1]
def partitions(n):
    p = [1] + [0] * n
    for k in range(1, n + 1):
        for j in range(k, n + 1): p[j] += p[j - k]
    return p[n]
def fib(n):
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a

